using System;using System.Collections.Generic;using System.Linq;using System.IO;using HabitatIsland;
public static class FeedbackSouthSolver {
 public static List<int[]> Route;static Tuning t=new Tuning{animalMovement=false};static int[] dx={0,1,0,-1},dz={1,0,-1,0};
 sealed class N{public HabitatState s;public List<int[]> p;public int d;}
 static Dictionary<int,List<int[]>> Walk(HabitatState s){var a=new Dictionary<int,List<int[]>>();var q=new Queue<int>();int first=s.playerZ*s.width+s.playerX;a[first]=new List<int[]>();q.Enqueue(first);while(q.Count>0){int n=q.Dequeue();for(int d=0;d<4;d++){int x=n%s.width+dx[d],z=n/s.width+dz[d];if(z<1||z>5||x<3||x>10)continue;var c=HabitatRules.Clone(s);c.playerX=n%s.width;c.playerZ=n/s.width;var before=c.tiles.Select(v=>v.prop).ToArray();if(!HabitatRules.MovePlayer(c,dx[d],dz[d],true,t)||!c.tiles.Select(v=>v.prop).SequenceEqual(before))continue;int k=c.playerZ*c.width+c.playerX;if(a.ContainsKey(k))continue;a[k]=new List<int[]>(a[n]){new[]{0,dx[d],dz[d]}};q.Enqueue(k);}}return a;}
 static string Key(HabitatState s,int reg)=>reg+":"+string.Join(";",s.tiles.Select((v,i)=>new{v,i}).Where(p=>p.i/s.width<=5&&HabitatRules.IsBox(p.v.prop)).Select(p=>p.i+","+(int)p.v.prop));
 static int Score(HabitatState s,int depth){int total=depth;foreach(var dest in new[]{new[]{6,5},new[]{9,5}}){int best=40;for(int i=0;i<s.tiles.Length;i++)if(i/s.width<=5&&HabitatRules.IsBox(s.tiles[i].prop))best=Math.Min(best,Math.Abs(i%s.width-dest[0])+Math.Abs(i/s.width-dest[1]));total+=best*8;}return total;}
 public static string Run(HabitatState initial){var open=new SortedDictionary<int,Queue<N>>();var seen=new HashSet<string>();Action<N> add=n=>{int k=Score(n.s,n.d);if(!open.TryGetValue(k,out var q)){q=new Queue<N>();open[k]=q;}q.Enqueue(n);};add(new N{s=initial,p=new List<int[]>()});int count=0;while(open.Count>0&&count<20000){int k=open.First().Key;var n=open[k].Dequeue();if(open[k].Count==0)open.Remove(k);var walk=Walk(n.s);if(!seen.Add(Key(n.s,walk.Keys.Min())))continue;count++;if(count%500==0)File.WriteAllText("Verification/feedback-221708/solver-progress.txt",count+" score="+k);if(n.s.animals.All(a=>HabitatRules.Evaluate(n.s,a,t).suitable)){Route=n.p;return "PASS actions="+n.p.Count+" states="+count;}
 foreach(var w in walk)for(int d=0;d<4;d++){int x=w.Key%n.s.width,z=w.Key/n.s.width,bx=x+dx[d],bz=z+dz[d];if(!HabitatRules.IsBox(HabitatRules.TileAt(n.s,bx,bz)?.prop??PropKind.None))continue;for(int type=0;type<3;type++){var c=HabitatRules.Clone(n.s);c.playerX=x;c.playerZ=z;c.events.Clear();bool ok=type==0?HabitatRules.PushBox(c,bx,bz):type==1?HabitatRules.PullPlayer(c,-dx[d],-dz[d]):HabitatRules.RecoverBox(c,bx,bz);if(!ok)continue;var p=new List<int[]>(n.p);p.AddRange(w.Value);p.Add(type==0?new[]{11,bx,bz}:type==1?new[]{12,-dx[d],-dz[d]}:new[]{13,bx,bz});add(new N{s=c,p=p,d=n.d+1});}}}return "FAIL states="+count;}
}
